```python
def mean_load(values):
    """Return mean kW load; empty or negative samples raise ValueError."""
    if not values or any(v < 0 for v in values):
        raise ValueError("nonempty nonnegative samples required")
    return sum(values) / len(values)

# mean_load([2, 4]) -> 3.0
# mean_load([]) raises ValueError
```

```python
def peak_load(values):
    """Peak kW, requiring nonempty nonnegative values."""
    if not values or any(v < 0 for v in values):
        raise ValueError("invalid readings")
    return max(values)

# peak_load([2, 7, 3]) -> 7
# peak_load([]) raises ValueError
```

```python
def capacity_factor(actual_kwh, rated_kw, hours):
    """Ratio of actual kWh to rated kW times hours; no clamping."""
    if actual_kwh < 0 or rated_kw <= 0 or hours <= 0:
        raise ValueError("invalid energy, capacity or duration")
    return actual_kwh / (rated_kw * hours)

# capacity_factor(50, 10, 10) -> 0.5
# capacity_factor(1, 0, 1) raises ValueError
```

```python
def battery_runtime(usable_kwh, load_kw):
    if load_kw <= 0 or usable_kwh < 0:
        raise ValueError("invalid input")
    return usable_kwh / load_kw
```

```python
def count_above(values, threshold):
    return sum(v >= threshold for v in values)

# count_above([1, 2, 3], 2) -> 2
```

```python
def load_factor(values):
    # mean divided by peak
    return sum(values) / len(values) / max(values)

# load_factor([2, 4]) -> 0.75
```
